function decode(row){
  return {
    model:MODEL_BY_CODE[row[0]],
    mapX:row[1],
    mapY:row[2],
    rotationY:row[3],
    scale:[row[4],row[5],row[6]],
    yOffset:row[7],
    normalSampleDistance:row[8],
    alignToTerrain:true
  };
}

/*
 * RAW is intentionally treated as source data only. Its original sector key
 * came from the offline geology sampler, and coordinates are serialized to
 * 0.1 m. A rounded coordinate can land exactly on a 512 m sector boundary.
 * Re-index every row with the same authoritative sectorForWorldPoint() path
 * used by terrain so placement and terrain can never disagree.
 */
function buildAuthoritativeIndex(){
  const index=new Map();
  const counts={s:0,m:0,c:0};
  let total=0;

  for(const rows of Object.values(RAW)){
    for(const row of rows){
      const sectorId=sectorIdForMapPoint(row[1],row[2]);

      if(!sectorId){
        throw new Error(
          'Ozeti v85 rock placement is outside master world: '+
          row[1]+','+row[2]
        );
      }

      if(!index.has(sectorId)){
        index.set(sectorId,[]);
      }

      index.get(sectorId).push(row);
      counts[row[0]]=(counts[row[0]]||0)+1;
      total++;
    }
  }

  return {index,counts,total};
}

const AUTHORITATIVE=buildAuthoritativeIndex();

export const ROCK_PLACEMENT_STATS=Object.freeze({
  'rock.small':AUTHORITATIVE.counts.s,
  'rock.medium':AUTHORITATIVE.counts.m,
  'rock.cliff':AUTHORITATIVE.counts.c,
  total:AUTHORITATIVE.total,
  sectors:AUTHORITATIVE.index.size
});

export function rockPlacementsForSector(sectorId){
  const rows=AUTHORITATIVE.index.get(sectorId)||[];
  return rows.map(decode);
}

export function activeRockSectorIds(){
  return [...AUTHORITATIVE.index.keys()].sort();
}
